    <!-- add binCard item starts -->
    <div class="modal fade mymodal" id="add-item-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="itemModalLabel" aria-hidden="true">
        <div class="modal-dialog modal-xl">
