                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closebinCardModal()" id="close_item"></button>
                </div>
                <form @submit.prevent="AddBinCardItem()">
                    <div class="modal-body">
                        <div class="row mb-3">
