    <!-- add binCard item ends -->

             <!-- Edit bin card item  modal starts -->
<div class="modal fade mymodal" id="edit-conversion-factor-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editConversionFactorModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
