 </div>
</template>

<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import globalSearchField from '@/components/reusables/globalSearchField.vue';
    import { globalSearch } from '@/components/reusables/globalSearch';
import Bincard from './assets/bincard.vue';
    
    useMeta({ title: 'statement of accounts' });  
    const waitIndicator = inject('waitIndicator');
    const showMessage = inject('showMessage');
    const conversion_factor = ref(false);
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    const filter = ref('')
    
    const loading_spinner = ref(false);
    const item_columns = ref(['SNo','date','ref_no','remark','dr','cr','balance','actions']);    
    const name = ref('');
    const remark = ref('');
    const description = ref('');
    const units = ref('');
    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'ref_no','received_Qty','issued_Qty','balance_Qty'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const unitList = ref([]);
    const getUnits = async () => {
        try {
            const response = await axiosInstance.get('/units');
            unitList.value = response.data;
        } catch (error) {
            showError(error.message);
        }
    };

    const formatNumber = (value) => {
  return new Intl.NumberFormat('en-US', { 
    minimumFractionDigits: 1, 
    maximumFractionDigits: 1 
  }).format(value);
};



    const calculateBinCardBalance = (items) => {
    if (!items || !items.length) return 0;

    return items.reduce((total, item) => {
        const received = parseFloat(item.received) || 0;
        const issued = parseFloat(item.issued) || 0;
        return total + received - issued;
    }, 0).toFixed(2);
};

    const binCards = ref([]);
    const issuer_id = ref('all')

    const getTableData = (items, binCard) => {
        if (!items) return [];
        
        let runningBalance = 0;
        return items.map((item, index) => {
            const received = parseFloat(item.received) || 0;
            const issued = parseFloat(item.issued) || 0;
            runningBalance += received - issued;
            
            return {
                id: item.id,
                SNo: index + 1,
                ref_no: item.ref_no,
                dr: item.received ? formatNumber(item.received) + ' ' + binCard.unit : '--',
                cr: item.issued ? formatNumber(item.issued) + ' ' + binCard.unit : '--',
                balance: formatNumber(runningBalance) + ' ' + binCard.unit,
                remark: item.remark,
                date: formatDate(item.date),
                authorized_by: item.issuer?.name || 'N/A',
            };
        });
    };

    const filteredBinCards = computed(() => {
    return globalSearch(binCards.value, filter.value);
});

    const loading = ref(false)
    const mount_state = ref(false)
    const getBinCards = async () => {
        if(user_permissions.includes('can_view_all_account_statements')){
           issuer_id.value = 'all'
        }else{
             issuer_id.value = JSON.parse(localStorage.getItem("user")).id
        }
        loading.value = true
        if(mount_state.value == true){
          loading_spinner.value = true;
        }
        
        try {
            const response = await axiosInstance.get(`bin-cards?no_store_item=1&issuer_id=${issuer_id.value}`);
            binCards.value = response.data.map((item, index) => ({
                ...item,
                SNo: index + 1,
                id: item.id,
                name: item.name,
                unit: item.unit,
                unit_name: item.unit,
                description: item.description || ' ',
                remark: item.remark,
                items: item.items,
                balance: calculateBinCardBalance(item.items)
            }));
        } catch (error) {
            console.log(error)
            showError(error.message);
        } finally {
            loading_spinner.value = false;
            loading.value = false
        }
    };
    
    const registerBinCard = async () => {
        const existingBinCard = binCards.value.find(card => {
            if (card.name === name.value) {
                return true;
            }
            return false;
        });

        if (existingBinCard) {
            showError('Record already exists!');
            return;
        }
        conversion_factor.value = false;
        const itemData = {
            name: name.value,
            unit: units.value.short_name,
            description: description.value,
            remark: remark.value,
            issuer_id : JSON.parse(localStorage.getItem('user')).id
        };
    
        try {
            const response = await axiosInstance.post('/bin-cards', itemData);
            getBinCards();
            showMessage('Record added!');
            resetForm();
        } catch (error) {
            showError(error.message);
            console.log(error)
        }
    };    

    const resetForm = () => {
        name.value = '';
        units.value = '';
        description.value = '';
    };

    const openAddItemModal = (row) => {
        bin_card_id.value = row.id; 
        binCard.value = row;
    };

    const isSending = ref(false);
    const received = ref('');
    const issued = ref('');
    const bin_card_id = ref('');
    const ref_no = ref('');
    const item = ref('');
    const binCard = ref('');
    const date = ref('');


    const canIssue = computed(() => {
    const currentBalance = parseFloat(binCard.value.balance || 0);
    const issuedQty = parseFloat(issued.value || 0);
    const receivedQty = parseFloat(received.value || 0);

    return issuedQty <= (currentBalance + receivedQty);
});




 const AddBinCardItem = async () => {

    const currentBalance = parseFloat(binCard.value.balance || 0);
    const issuedQty = parseFloat(issued.value || 0);
    const receivedQty = parseFloat(received.value || 0);

    if (issuedQty > (currentBalance + receivedQty)) {
        showError(`Issued quantity (${formatNumber(issuedQty)}) exceeds available balance (${formatNumber(currentBalance)})`);
        return;
    }

    isSending.value = true;

    const itemData = {
        bin_card_id: bin_card_id.value, 
        ref_no: ref_no.value,    
        received: received.value,
        issued: issued.value,
        issuer_id: JSON.parse(localStorage.getItem("user")).id,
        remark: remark.value,
        date: date.value,
    };

    try {  
        await axiosInstance.post(`bin-card-items`, itemData);
        showMessage('Transaction added');
        document.getElementById('close_item').click();
        getBinCards();
        closebinCardModal();
    } catch(error) {
        showError(error.message);
    } finally {
        isSending.value = false;    
    }
};


    const closebinCardModal = () => {
        ref_no.value = '';
        received.value = '';
        issued.value = '';
        remark.value = '';
        date.value = '';
    };

   const printAccountStatement = async (binCard) => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const tableData = getTableData(binCard.items, binCard);

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Financial Statement - ${binCard.name}</title>
<style>
  body { font-family: 'Courier New', monospace; margin: 40px; font-size: 13px; }
  .text-style { font-family: 'Courier New', monospace; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 20px; margin: 10px 0; }
  .subtitle { text-align: center; font-size: 16px; margin: 5px 0; my-4 }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th, td { border: 0.5px solid #000; padding: 6px; }
  th { background-color: #f8f8f8; font-weight: bold; }
  .text-right { text-align: right; }
