    const getStoreItems = (id) => {
        axiosInstance.get(`/get-store-items?store_id=${id}`).then((response) => {
            storeItems.value = response.data
            .map((store,index) => ({
                ...store,
                SNo: index + 1,
                name: store?.name + ' ' + (store?.condition ?? ''),
                category : store?.category_name,
                used: store?.used_quantity || 0,
                balance : store?.balance_quantity || 0,
                stock: store?.total_quantity || 0,
                checked : false
            }));
            loading_spinner.value = false;
        });
    };

    watch(store, (newVal) => {
        storeItem.value = ''
        storeItems.value = ['']
        getStoreItems(newVal.id)
    });

    const deletingItemId = ref(null);

    const deleteBinCardItem = async (item) => {
      deletingItemId.value = item.id;
      try {
        await axiosInstance.delete(`/bin-card-items/${item.id}`);
        await getBinCards();
        showMessage('Bin Card Item deleted successfully');
      } catch (error) {
        console.error(error);
        showError(error.message);
      } finally {
        deletingItemId.value = null;
      }
    };

  

    const bin_card_item_id = ref('');
